<script setup lang="ts">
// B3 单张工单成本明细（抽屉）。规格 unified-spec/B-cost-analysis.md §B3/§B5。两个工作区共用，来源链接由工作区配置给出。
import {computed,ref,watch} from 'vue'
import UButton from '@nuxt/ui/components/Button.vue'
import UBadge from '@nuxt/ui/components/Badge.vue'
import {adoptedOf,bjTime,type ShiftHours,sourceName,fmtCost as fmt,fmtPct,moneyUnit,stateLabel,unitCost,analysisLines,gapOf,followLabel,type CostOrder,type CostWorkspaceConfig} from './cost-review'
const props=defineProps<{order:CostOrder;config:CostWorkspaceConfig;sectionValue?:"material"|"labor"|"evidence";savedAnalysis?:{status:string;answer?:string;error?:string|null}}>()
const emit=defineEmits<{"update:sectionValue":[value:"material"|"labor"|"evidence"];analyze:[];supplement:[];followup:[];related:[id:string]}>()
const section=computed({get:()=>props.sectionValue||'material',set:(value:'material'|'labor'|'evidence')=>emit('update:sectionValue',value)})
const currency=computed(()=>moneyUnit(props.order.currency)),complete=computed(()=>props.order.materialCost!==null&&props.order.laborCost!==null),total=computed(()=>props.order.directCost)
const canStack=computed(()=>total.value!==null&&total.value>0&&props.order.materialCost!>=0&&props.order.laborCost!>=0)
const sections=[{id:'material',label:'材料与领退料'},{id:'labor',label:'人工与工序'},{id:'evidence',label:'依据与跟进'}] as const
const savedLines=computed(()=>analysisLines(props.savedAnalysis?.answer||'')),gap=computed(()=>gapOf(props.order))
const hours=computed(()=>{const k=props.order.processes.map(p=>p.personHours);return k.some(h=>h===null)?null:(k as number[]).reduce((n,h)=>n+h,0)})
const link=(kind:Parameters<CostWorkspaceConfig['sourceLink']>[0],id?:string)=>props.config.sourceLink(kind,props.order,id)
const av=computed(()=>adoptedOf(props.order))
const cols=computed(()=>({required:(props.order.materialTrace||[]).some(t=>t.required!==null),issued:(props.order.materialTrace||[]).some(t=>t.issued!==null),returned:(props.order.materialTrace||[]).some(t=>t.returned!==null)}))
// 来源标记用 D 线共享 sourceTag（SHARED.md 第 1 批）；共享脚本未加载时退回文字徽标
const cretasTag=computed(()=>{const u=(window as unknown as {CretasUI?:{sourceTagHTML?:(s:string)=>string}}).CretasUI;return u?.sourceTagHTML?u.sourceTagHTML('cretas'):''})
// 第四批③：按班次规则的有效工时，A 的接口算，这里只读
const shift=ref<ShiftHours|null|undefined>(undefined)
watch(()=>[props.order.id,section.value],async()=>{if(section.value!=='labor'||!props.config.features.shiftHours)return;shift.value=undefined;try{shift.value=await props.config.features.shiftHours(props.order)}catch{shift.value=null}},{immediate:true})
const hrs=(sec:number|null|undefined)=>sec==null?'—':fmt(sec/3600)
const shiftSum=computed(()=>{const rows=shift.value&&shift.value.available?shift.value.rows:[];const ok=rows.filter(r=>r.status==='已计算'),miss=rows.filter(r=>r.status!=='已计算');const reasons=Object.entries(miss.reduce((m,r)=>(m[r.status]=(m[r.status]||0)+1,m),{} as Record<string,number>)).map(([k,v])=>k+' '+v+' 条').join('、');return {ok:ok.length,miss:miss.length,reasons,eff:ok.reduce((n,r)=>n+(r.effectiveSeconds||0),0),bl:ok.reduce((n,r)=>n+(r.blacklakeEffectiveSeconds||0),0)}})
// BL15：效率与达标率由生产线（A）计算，这里只读显示
const eff=ref<Awaited<ReturnType<NonNullable<CostWorkspaceConfig['features']['efficiency']>>>|undefined>(undefined)
watch(()=>[props.order.id,section.value],async()=>{if(section.value!=='labor'||!props.config.features.efficiency)return;eff.value=undefined;try{eff.value=await props.config.features.efficiency(props.order)}catch{eff.value=null}},{immediate:true})
const canSupplement=computed(()=>props.order.processes.length>0||props.config.factoryId!=='YDWM'&&(props.order.sourceMaterialCost===null||props.order.sourceMaterialCost===0))
</script>
<template>
 <section class="nuxt-batch-review" aria-label="工单成本明细">
  <div class="nuxt-cost-heading"><div><p><span v-if="order.synthetic">模拟批次 · </span>{{order.product}} · {{order.planNumber||'未关联计划'}} · {{config.label}}</p></div><UBadge color="neutral" variant="subtle">{{stateLabel(order.status)}}</UBadge></div>
  <div class="nuxt-demo-row cost-drawer-actions" aria-label="本工单操作">
   <UButton label="补充资料" size="xs" :disabled="!canSupplement" :title="canSupplement?'补充本工单的人工、有效人时与实际参与名单；只用于分析，不回写原账':'本工单尚无确定工序对应，先回来源核对报工（只能补材料估值时除外）'" @click="emit('supplement')"/>
   <UButton label="记录跟进" size="xs" color="neutral" variant="outline" title="记录本工单的核对进展；已核对不清除资料缺口" @click="emit('followup')"/>
   <UButton label="解读这张工单" size="xs" color="neutral" variant="ghost" title="把本工单交给右下角悬浮窗：成本从哪来、缺什么、找谁补。不改金额，不保存" @click="emit('analyze')"/>
  </div>
  <section v-if="order.weigh" class="nuxt-batch-composition cost-weigh" aria-label="报工称重"><div class="nuxt-cost-heading"><h3>报工称重 · Cretas（主来源）</h3><small>{{order.weigh.records??'—'}} 笔<template v-if="order.weigh.lastAt"> · 最近录入 {{bjTime(order.weigh.lastAt)}}</template></small></div>
   <p v-if="order.weigh.missing||order.weigh.incomplete" class="cost-warn-text" role="note">{{order.weigh.missing||order.weigh.incomplete}}<template v-if="order.weigh.incomplete">。产出量和单位成本暂按原来源，已称工序只算各自的出成率，不拿中间工序顶替</template>。</p>
   <div class="nuxt-review-metrics"><div><span>完工良品 · Cretas</span><strong>{{fmt(order.weigh.goodKg)}}<small>kg · {{order.weigh.routeFinal?.name||order.weigh.finalProcess?.name||'完工工序未认定'}}<template v-if="!order.weigh.complete">（未称重）</template></small></strong></div><div><span>首道投入 · Cretas</span><strong>{{fmt(order.weigh.inputKg)}}<small>kg · {{order.weigh.firstProcess?.name||'—'}}<template v-if="order.weigh.firstProcess&&!order.weigh.firstProcess.weighed">（未称重）</template></small></strong></div><div><span>整单出成率 · Cretas</span><strong>{{order.weigh.yieldRate==null?'—':fmtPct(order.weigh.yieldRate)}}<small>完工良品 ÷ 首道投入<template v-if="order.weigh.yieldRate==null"> · 缺一端不计算</template></small></strong></div><div><span>不良 · Cretas</span><strong>{{fmt(order.weigh.defectKg)}}<small>kg</small></strong></div></div>
   <div class="nuxt-cost-scroll"><table class="nuxt-cost-table" aria-label="各工序出成率"><thead><tr><th>工序（按路线）</th><th>投入 kg</th><th>良品 kg</th><th>不良 kg</th><th>工序出成率</th><th>笔数</th></tr></thead><tbody><tr v-for="p in order.weigh.processes" :key="p.code"><td>{{p.name}}<small v-if="p.isLast">完工工序 · 产出量取这一道</small><small v-else-if="p.isFirst">首道</small><small v-else>中间工序 · 只算本工序出成率</small></td><td>{{fmt(p.inputKg)}}</td><td>{{fmt(p.goodKg)}}</td><td>{{fmt(p.defectKg)}}</td><td>{{p.yieldRate==null?'—':fmtPct(p.yieldRate)}}</td><td>{{p.records??'—'}}</td></tr></tbody></table></div>
   <p class="nuxt-muted">{{order.weigh.basis}}</p>
   <p v-if="order.weigh.byproducts.length">副产品（Cretas）：<template v-for="(b,i) in order.weigh.byproducts" :key="b.name">{{i?'、':''}}{{b.name}} {{fmt(b.kg)}} kg</template>，合计 {{fmt(order.weigh.byproductKg)}} kg。</p><p v-else class="nuxt-muted">没有登记副产品。</p>
   <p>口径：{{order.weigh.rule.text}}<template v-if="order.weigh.mainCost!==null">；主产品承担 {{fmt(order.weigh.mainCost)}} {{currency}}<template v-if="order.weigh.byproductCost">，副产品承担 {{fmt(order.weigh.byproductCost)}} {{currency}}</template></template>。每 kg 良品：材料 {{fmt(order.weigh.materialUnit)}}、人工 {{fmt(order.weigh.laborUnit)}}、合计 {{fmt(order.weigh.unitCost)}} {{currency}}<template v-if="order.weigh.blockedReason">（{{order.weigh.blockedReason}}）</template><template v-else-if="order.weigh.note">（{{order.weigh.note}}）</template>。</p>
   <p class="nuxt-muted">对照：黑湖实际产量 {{order.weigh.compare.blacklake?fmt(order.weigh.compare.blacklake.value)+' '+(order.weigh.compare.blacklake.unit||''):'黑湖成本接口未返回'}}；黑湖报工良品 {{fmt(order.weigh.compare.cretasReport.value)}} {{order.weigh.compare.cretasReport.unit||''}}。称重是主来源，两边不互相覆盖，差异由 A 线对账清单处理。</p></section>
  <!-- 有黑湖成本时，顶部指标显示「采用值」并逐项标来源（R13：金额黑湖 0 不算有值；数量以黑湖为准）；没有时显示 Cretas 计算 -->
  <div v-if="av" class="nuxt-review-metrics" aria-label="采用值"><div><span>单位直接成本 · 采用：{{av.label}}<template v-if="av.weighed"> · 产出 Cretas 称重</template></span><strong>{{fmt(av.unitCost)}}<small><template v-if="av.blockedReason">{{av.blockedReason}}</template><template v-else>{{currency}} / {{av.output.unit||order.unit||'单位待核对'}}</template></small></strong></div><div><span>材料费 · {{av.material.blocked?'采用：—':sourceName(av.material.source)}}</span><strong>{{fmt(av.material.value)}}<small>{{currency}}<template v-if="av.material.note"> · {{av.material.note}}</template></small></strong></div><div><span>人工费 · {{av.labor.blocked?'采用：—':sourceName(av.labor.source)}}</span><strong>{{fmt(av.labor.value)}}<small>{{currency}}<template v-if="av.labor.note"> · {{av.labor.note}}</template></small></strong></div><div><span>{{av.weighed?'良品重量':'实际产量'}} · {{sourceName(av.output.source)==='—'?'黑湖':sourceName(av.output.source)}}</span><strong>{{fmt(av.output.value)}}<small>{{av.output.unit||''}}<template v-if="av.output.note"> · {{av.output.note}}</template></small></strong></div></div>
  <div v-else class="nuxt-review-metrics"><div><span>单位直接成本</span><strong>{{fmt(unitCost(order))}}<small>{{currency}} / {{order.unit||'单位待核对'}}</small></strong></div><div><span>材料费</span><strong>{{fmt(order.materialCost)}}<small>{{currency}}<template v-if="order.materialCost===0"> · 已记录零值</template></small></strong></div><div><span>人工费</span><strong>{{fmt(order.laborCost)}}<small>{{currency}}<template v-if="order.laborCost===0"> · 已记录零值</template></small></strong></div><div><span>已记录良品</span><strong>{{fmt(order.finishedGood)}}<small>{{order.unit||'单位待核对'}}</small></strong></div></div>
  <p v-if="order.blacklake?.supplementState" class="cost-supp-note"><span v-if="cretasTag" v-html="cretasTag"/><UBadge v-else color="info" variant="subtle">含 Cretas 补充</UBadge> {{order.blacklake.supplementState}}。</p>
  <p v-else-if="order.supplementFields?.length||order.supplementNote" class="cost-supp-note"><span v-if="cretasTag" v-html="cretasTag"/><UBadge v-else color="info" variant="subtle">含 Cretas 补充</UBadge> {{order.supplementFields?.join('、')}}<template v-if="order.supplementFields?.length"> 来自 Cretas 补充，其余字段来自{{config.factoryId==='YDWM'?'本工作区记录':'黑湖'}}。</template><span v-if="order.supplementNote" class="nuxt-muted"> {{order.supplementNote}}。</span></p>
  <div class="nuxt-review-summary"><strong>结论</strong>
   <p v-if="order.reportLineage">已定位对应报工，请查看实际报工批次；本条开工记录不重复补产量和成本。</p>
   <p v-else-if="av&&av.blockedReason">采用：—。{{av.blockedReason}}。不回退用 Cretas 值顶替；已列入待补资料。</p>
   <p v-else-if="av&&av.weighed&&av.unitCost!==null&&order.weigh">采用：金额 {{av.label}}，产出取 Cretas 称重完工良品 {{fmt(order.weigh.goodKg)}} kg（整单出成率 {{order.weigh.yieldRate==null?'缺：'+(order.weigh.missing||'首道或完工工序未称重'):fmtPct(order.weigh.yieldRate)}}），每 kg 直接成本 {{fmt(av.unitCost)}} {{currency}}，{{order.weigh.rule.text}}。<template v-if="unitCost(order)!==null">Cretas 计算按黑湖报工良品 {{fmt(order.finishedGood)}} {{order.unit||''}} 算是每{{order.unit||'单位'}} {{fmt(unitCost(order))}} {{currency}}<template v-if="/^kg$/i.test(order.unit||'')">；两边都是 kg，差在分母：称重采用值除以完工良品 {{fmt(order.weigh.goodKg)}} kg，Cretas 计算除以黑湖报工良品 {{fmt(order.finishedGood)}} kg<template v-if="order.weigh.rule.mode!=='none'">，采用值另按副产品口径分摊</template></template><template v-else>；单位不同（{{order.unit||'单位待核对'}} 对 kg），不直接比较</template>。</template></p>
   <p v-else-if="av&&av.unitCost!==null">采用：{{av.label}}，每{{av.output.unit||order.unit}}直接成本 {{fmt(av.unitCost)}} {{currency}}（材料 {{sourceName(av.material.source)}}、人工 {{sourceName(av.labor.source)}}<template v-if="av.outsourceOther">、含黑湖委外/其他 {{fmt(av.outsourceOther.value)}}</template>）。<template v-if="order.blacklake?.supersededFields?.length">{{order.blacklake.supersededFields.join('、')}}的 Cretas 补充已被来源值取代，不参与采用值。</template>Cretas 计算为 {{fmt(unitCost(order))}}，差异见下方对照表。</p>
   <p v-else-if="av">采用值暂不能计算单位成本（{{av.material.value===null?'材料：'+av.material.note:av.labor.value===null?'人工：'+av.labor.note:'实际产量为 0 或缺失'}}）；未填写项不补成 0。<template v-if="order.blacklake?.supersededFields?.length">{{order.blacklake.supersededFields.join('、')}}的 Cretas 补充已被来源值取代，不参与采用值。</template></p>
   <p v-else-if="unitCost(order)!==null">每{{order.unit}}已识别直接成本 {{fmt(unitCost(order))}} {{currency}}（材料＋人工，不含制造费用）。</p>
   <p v-else-if="order.finishedGood===0">良品产出已记录为 0，不能计算单位成本；这不是产出缺失。</p>
   <p v-else>单位直接成本暂不能计算：{{gap?.label||'资料或口径待核'}}。未填写项不补成 0。</p>
   <p v-if="gap"><b>找 {{gap.owner}}</b>：{{gap.reasons.join('；')}}。补齐后：{{gap.unlocks}}。<span v-if="gap.others.length" class="nuxt-muted">另有：{{gap.others.join('、')}}。</span></p>
   <p v-if="!canSupplement&&!order.reportLineage" class="nuxt-muted">尚无确定工序对应，请先从来源核对报工，不能分摊到虚构工序。</p>
  </div>
  <section v-if="order.reportLineage" class="nuxt-review-summary" aria-label="已核实的报工对应关系"><h3>报工关系已核实</h3><p>{{order.reportLineage.boundary}}</p><table class="nuxt-cost-table"><thead><tr><th>实际报工批次</th><th>工序 / 报工ID</th><th>提交时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in order.reportLineage.reports" :key="r.reportId"><td>{{r.batchNumber}}</td><td>{{r.processName}}<small>{{r.processId}} · {{r.reportId}}</small></td><td>{{r.submittedAt}}</td><td><UButton label="报工" color="neutral" variant="outline" size="xs" @click="emit('related',r.batchId)"/></td></tr></tbody></table><details><summary>关系依据</summary><p>{{order.reportLineage.basis}}</p><small>证据版本 {{order.reportLineage.proofHash}}</small></details></section>
  <div v-if="av" class="nuxt-batch-composition"><div class="nuxt-cost-heading"><h3>直接成本构成 · 采用：{{av.label}}</h3><strong>{{fmt(av.total)}} {{currency}}</strong></div><p v-if="av.blockedReason" class="cost-warn-text">{{av.blockedReason}}</p><template v-else-if="av.total"><div class="nuxt-review-stack" aria-label="采用值材料与人工构成"><span :style="{width:Math.max(0,av.material.value||0)/av.total*100+'%'}"/><span :style="{width:Math.max(0,av.labor.value||0)/av.total*100+'%'}"/></div><p>材料 {{fmt(av.material.value)}}（{{sourceName(av.material.source)}}）· 人工 {{fmt(av.labor.value)}}（{{sourceName(av.labor.source)}}）<template v-if="av.outsourceOther"> · 委外/其他 {{fmt(av.outsourceOther.value)}}（黑湖）</template> {{currency}}<span class="nuxt-muted"> · 不含未归集制造费用</span></p><p v-if="order.blacklake?.supersededFields?.length" class="nuxt-muted">{{order.blacklake.supersededFields.join('、')}}的 Cretas 补充已被来源值取代，不计入构成。</p></template></div>
  <div v-else class="nuxt-batch-composition"><div class="nuxt-cost-heading"><h3>直接成本构成</h3><strong>{{fmt(total)}} {{currency}}<small v-if="!complete"> · 未完整</small></strong></div><div v-if="canStack" class="nuxt-review-stack" aria-label="工单材料与人工成本构成"><span :style="{width:order.materialCost!/total!*100+'%'}"/><span :style="{width:order.laborCost!/total!*100+'%'}"/></div><p>材料 {{fmt(order.materialCost)}}<template v-if="canStack"> · {{fmtPct(order.materialCost!/total!)}}</template> · 人工 {{fmt(order.laborCost)}}<template v-if="canStack"> · {{fmtPct(order.laborCost!/total!)}}</template> {{currency}}<span class="nuxt-muted"> · 不含未归集制造费用</span></p></div>
  <section v-if="order.blacklake" class="cost-bl" aria-label="黑湖成本与 Cretas 计算对照">
   <div class="nuxt-cost-heading"><h3>黑湖成本 与 Cretas 计算</h3><small v-if="order.blacklake.available">采用：<b>{{order.blacklake.adoptedLabel||'—'}}</b></small></div>
   <p v-if="!order.blacklake.available" class="nuxt-muted">{{order.blacklake.reason}}；以下只有 Cretas 计算。</p>
   <template v-else>
    <p class="nuxt-muted">{{order.blacklake.adoptedNote}}。黑湖成本接口状态「{{order.blacklake.status}}」，更新于 {{String(order.blacklake.updatedAt||'').slice(0,16).replace('T',' ')}}。</p>
    <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>项目</th><th>黑湖成本</th><th>Cretas 计算</th><th>差额（黑湖−Cretas）</th><th>原因</th></tr></thead><tbody>
     <tr v-for="it in order.blacklake.items" :key="it.field"><td>{{it.field}}</td><td>{{fmt(it.blacklake)}}</td><td>{{it.cretas===null&&(it.field==='委外'||it.field==='其他')?'不含':fmt(it.cretas)}}</td><td>{{fmt(it.delta)}}</td><td><span :class="it.reason.code==='MATCH'?'cost-ok':'cost-warn-text'">{{it.reason.text}}</span></td></tr>
     <tr class="cost-total"><td>合计</td><td>{{fmt(order.blacklake.total?.blacklake)}}</td><td>{{fmt(order.blacklake.total?.cretas)}}</td><td>{{fmt(order.blacklake.total?.delta)}}</td><td>{{currency}}<template v-if="order.blacklake.supersededFields?.length"> · Cretas 列含已被取代的{{order.blacklake.supersededFields.join('、')}}补充，仅作对照</template></td></tr>
     <tr><td>产出</td><td>{{fmt(order.blacklake.output?.blacklake)}} {{order.blacklake.output?.unitBlacklake}}</td><td>{{fmt(order.blacklake.output?.cretas)}} {{order.blacklake.output?.unitCretas}}</td><td/><td>{{order.blacklake.unitCost?.reason?.text||''}}</td></tr>
     <tr><td>单位成本</td><td>{{fmt(order.blacklake.unitCost?.blacklake)}}</td><td>{{fmt(order.blacklake.unitCost?.cretas)}}</td><td>{{order.blacklake.unitCost?.blacklake!=null&&order.blacklake.unitCost?.cretas!=null&&!order.blacklake.unitCost?.reason?fmt(order.blacklake.unitCost.blacklake-order.blacklake.unitCost.cretas):'—'}}</td><td>{{currency}} / {{order.blacklake.output?.unitBlacklake||order.unit}}</td></tr>
    </tbody></table></div>
    <p class="nuxt-muted">黑湖预估：合计 {{fmt(order.blacklake.estimate?.total)}}（材料 {{fmt(order.blacklake.estimate?.material)}}、人工 {{fmt(order.blacklake.estimate?.labor)}}），实际与预估差额 {{fmt(order.blacklake.estimate?.differenceAmount)}}<template v-if="order.blacklake.estimate?.differenceRate!=null">（{{fmtPct(order.blacklake.estimate.differenceRate)}}）</template>。差额原因由代码按两边数值判断；「差异待核对」不代表已查明原因。</p>
    <details><summary>黑湖成本来源明细 · {{order.blacklake.detailCount}} 条</summary>
     <table class="nuxt-cost-table"><thead><tr><th>类型 / 来源</th><th>条数</th><th>金额</th></tr></thead><tbody><tr v-for="b in order.blacklake.breakdown" :key="b.type+b.source"><td>{{b.type}} · {{b.source}}</td><td>{{b.count}}</td><td>{{fmt(b.amount)}}</td></tr></tbody></table>
     <p class="nuxt-muted">实际材料＝「实际领退料」之和（退料为负）；「BOM 需求」「预估单价」只用于黑湖预估，不计入实际。</p>
     <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>类型</th><th>物料 / 工序</th><th>数量 / 工时</th><th>单价</th><th>金额</th></tr></thead><tbody><tr v-for="(l,i) in order.blacklake.lines" :key="i"><td>{{l.type}}<small>{{l.biz||l.source}}</small></td><td>{{l.name}}</td><td>{{l.hours!=null?fmt(l.hours)+' 小时 · 良品 '+fmt(l.qty):fmt(l.qty)+' '+(l.unit||'')}}</td><td>{{fmt(l.unitPrice)}}</td><td>{{fmt(l.amount)}}</td></tr></tbody></table></div></details>
   </template>
  </section>
  <nav class="nuxt-review-tabs" aria-label="工单成本依据"><UButton v-for="item in sections" :key="item.id" :label="item.label" :variant="section===item.id?'soft':'ghost'" :color="section===item.id?'primary':'neutral'" size="xs" @click="section=item.id"/></nav>
  <section v-if="section==='material'" aria-label="工单材料证据"><h3>材料花在哪里</h3><p class="nuxt-muted"><template v-if="av">材料费（采用：{{av.material.blocked?'—':sourceName(av.material.source)}}）{{fmt(av.material.value)}} {{currency}}<template v-if="order.blacklake?.supersededFields?.includes('材料费')">；材料费的 Cretas 补充已被来源值取代，不参与采用值</template>。</template><template v-else>材料费 {{fmt(order.materialCost)}} {{currency}}。</template>下表是{{config.factoryId==='YDWM'?'同计划领退料，不能直接认定为本批实耗':'本工单关联的领退料净耗与已识别金额'}}。</p>
   <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>领料单 / 物料</th><th v-if="cols.required">需求</th><th v-if="cols.issued">已发</th><th>{{cols.issued?'实耗':'净耗'}}</th><th v-if="cols.returned">退回</th><th>行成本</th><th>来源</th></tr></thead><tbody>
    <tr v-for="t in order.materialTrace" :key="t.id"><td>{{t.document}}<small>{{t.material}} · {{stateLabel(t.status)}}</small></td><td v-if="cols.required">{{fmt(t.required)}} {{t.unit}}</td><td v-if="cols.issued">{{fmt(t.issued)}} {{t.unit}}</td><td>{{fmt(t.consumed)}} {{t.unit}}</td><td v-if="cols.returned">{{fmt(t.returned)}} {{t.unit}}</td><td>{{fmt(t.recordedLineCost)}}</td><td><a v-if="link('material',t.document)" class="nuxt-cost-link" :href="link('material',t.document)!">原单</a><small v-else>未提供链接</small></td></tr>
    <tr v-if="!order.materialTrace?.length"><td colspan="7">暂无可关联的领退料明细，不估算逐料金额。</td></tr></tbody></table></div>
   <p v-if="order.materialTrace?.some(t=>t.consumed===0)" class="nuxt-muted">实耗 0.00 是已记录的零值；不能把已发量改称实耗。</p>
   <p v-if="order.materialTrace?.some(t=>t.recordedLineCost===0)" class="nuxt-muted">行成本 0.00 是源端零值，需确认历史估值；不等于免费原料。</p></section>
  <section v-else-if="section==='labor'" aria-label="工单人工分析"><h3>人工与工序成本</h3>
   <div class="nuxt-review-metrics nuxt-review-metrics-three"><div><span>本单人工费<template v-if="av"> · {{av.labor.blocked?'采用：—':sourceName(av.labor.source)}}</template></span><strong>{{fmt(av?av.labor.value:order.laborCost)}}<small>{{currency}}<template v-if="order.blacklake?.supersededFields?.includes('人工费')"> · 人工费补充已被取代</template></small></strong></div><div><span>实际参与人数</span><strong>{{order.participants===null?'未提供':order.participants}}<small>本单去重人数</small></strong></div><div><span>人均人工费</span><strong>{{fmt(order.perPerson)}}<small>{{order.participants===null?'缺实际参与名单，不计算':currency+' / 人'}}</small></strong></div></div>
   <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>工序 / 依据</th><th>有效人时</th><th>人时占比</th><th>人工分摊</th><th>人工占比</th><th v-if="config.features.wageRules">工价规则</th><th>来源</th></tr></thead><tbody>
    <tr v-for="p in order.processes" :key="p.id"><td>{{p.name}}<small>{{p.source}}</small></td><td>{{fmt(p.personHours)}}</td><td>{{hours&&p.personHours!==null?fmtPct(p.personHours/hours):'—'}}</td><td>{{fmt(p.allocatedLabor)}} {{currency}}</td><td>{{order.laborCost&&p.allocatedLabor!==null?fmtPct(p.allocatedLabor/order.laborCost):'—'}}</td><td v-if="config.features.wageRules">{{p.ruleLabor!=null?fmt(p.ruleLabor)+' '+currency:'—'}}<small v-if="p.ruleReason">{{p.ruleReason}}</small></td><td><a v-if="link('task',p.id)" class="nuxt-cost-link" :href="link('task',p.id)!">工序</a><small v-else>—</small></td></tr>
    <tr v-if="!order.processes.length"><td colspan="7">工序对应关系待补</td></tr></tbody></table></div>
   <p v-if="config.features.wageRules" class="cost-rule-note"><b>工价规则（Cretas 补充）</b>：<template v-if="order.ruleLabor!=null">按规则合计 {{fmt(order.ruleLabor)}} {{currency}}<template v-if="order.ruleLaborDelta!=null&&Math.abs(order.ruleLaborDelta)<0.005">，与{{order.sourceLaborCost!==null?'黑湖记录':'已记录'}}人工费一致（差额 0.00）</template><template v-else-if="order.ruleLaborDelta!=null">，与{{order.sourceLaborCost!==null?'黑湖记录':'已记录'}}人工费相差 {{fmt(order.ruleLaborDelta)}} {{currency}}（差额待核对，不改黑湖）</template><template v-else-if="order.supplementFields?.includes('人工费（工价规则）')">；黑湖缺人工费，本单人工费取规则结果</template>。</template><template v-else>{{order.ruleLaborPartial?'部分报工没有匹配到规则，合计不计算':'未设置适用规则'}}；黑湖工资有值时以黑湖为准。</template></p>
   <div v-if="config.features.shiftHours" class="cost-eff" aria-label="按班次规则的有效工时"><b>按班次规则的有效工时（生产线计算，只读）</b><p v-if="shift===undefined" class="nuxt-muted">读取中…</p><p v-else-if="shift===null||!shift.available" class="nuxt-muted">{{shift?.reason||'生产线没有返回班次工时'}}</p><template v-else><p class="nuxt-muted">班次规则：{{shift.ruleName||'未配置班次规则（Cretas 补充，在生产线维护）'}}。{{shift.formula}}。只作对照，人工费仍按黑湖或采用值，不按本表重算。</p><p><b>已计算 {{shiftSum.ok}} 条</b><template v-if="shiftSum.ok">（有效工时合计 {{hrs(shiftSum.eff)}} 小时，对应黑湖工时 {{hrs(shiftSum.bl)}} 小时）</template>；<b>未计入 {{shiftSum.miss}} 条</b><template v-if="shiftSum.miss">：{{shiftSum.reasons}}</template>。未计入的不按 0 算。</p><div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>报工</th><th>黑湖工时（小时）</th><th>按班次有效工时</th><th>休息</th><th>加班</th><th>状态</th></tr></thead><tbody><tr v-for="r in shift.rows" :key="r.reportId"><td>{{r.reportId}}<small>{{r.start}} – {{r.end}}</small></td><td>{{hrs(r.blacklakeEffectiveSeconds)}}</td><td>{{r.status==='已计算'?hrs(r.effectiveSeconds):'—'}}</td><td>{{r.status==='已计算'?hrs(r.breakSeconds):'—'}}</td><td>{{r.status==='已计算'?hrs(r.overtimeSeconds):'—'}}</td><td>{{r.status}}</td></tr><tr v-if="!shift.rows.length"><td colspan="6">本工单没有报工。</td></tr></tbody></table></div></template></div>
   <div v-if="config.features.efficiency" class="cost-eff"><b>效率与达标率（生产线计算，只读）</b><p v-if="eff===undefined" class="nuxt-muted">读取中…</p><p v-else-if="eff===null" class="nuxt-muted">生产线尚未提供本工单的效率数据。</p><table v-else class="nuxt-cost-table"><thead><tr><th>工序</th><th>标准</th><th>实际</th><th>效率</th><th>达标率</th></tr></thead><tbody><tr v-for="r in eff.rows" :key="r.process"><td>{{r.process}}</td><td>{{r.standard??'—'}}</td><td>{{r.actual??'—'}}</td><td>{{r.efficiency==null?'—':fmtPct(r.efficiency)}}</td><td>{{r.passRate==null?'—':fmtPct(r.passRate)}}<small v-if="r.reason">{{r.reason}}</small></td></tr></tbody></table><small v-if="eff&&eff.note">{{eff.note}}</small></div>
   <p class="nuxt-muted">按各工序有效人时分摊同一笔人工费，分摊不再加一次；零人时或人时未知时不算比例。人均人工费不是工资或绩效，代报人、计划人数不能替代实际名单。</p></section>
  <section v-else aria-label="工单核对依据"><h3>依据与跟进</h3>
   <article v-for="r in order.requests" :key="r.field" class="nuxt-review-request"><strong>{{r.field}}</strong><p>找 {{r.owner}}：{{r.action}}</p></article>
   <p v-if="!order.requests.length">当前直接成本资料可用；完整制造成本范围仍需另行核实。</p>
   <details v-if="order.supplementEvidence" open><summary>已保存补充依据</summary><p v-if="order.blacklake?.supersededFields?.length" class="cost-warn-text">{{order.blacklake.supersededFields.join('、')}}的补充已被黑湖来源值取代，不参与采用值；以下依据仅作留痕。</p><p>{{order.supplementEvidence}}</p><small>{{order.supplementAt}}</small></details>
   <div class="nuxt-review-summary"><strong>跟进状态：{{followLabel(order.followup?.status)}}</strong><p>{{order.followup?.note||'尚未记录跟进说明'}}</p><small>已核对只是跟进记录，不清除资料缺口或成本核算阻断。</small></div>
   <details><summary>已保存的逐单解读</summary><div v-if="savedAnalysis?.status==='COMPLETE'" class="nuxt-batch-saved"><template v-for="(line,index) in savedLines" :key="index"><h4 v-if="line.heading">{{line.text}}</h4><p v-else>{{line.text}}</p></template></div><p v-else>{{savedAnalysis?.error||(config.features.batchAnalysis?'本单尚无当前依据下已通过的解读；可在「周期成本」报告卡逐单核对。':'本工作区未提供逐单核对。')}}</p></details></section>
  <footer class="nuxt-batch-source"><span>回到原始业务</span><a v-if="link('plan')" :href="link('plan')!">来源{{config.factoryId==='YDWM'?'计划':'工单'}}</a><a v-if="link('canvas')" :href="link('canvas')!">工序 / BOM</a><small>补充只用于分析，不回写{{config.factoryId==='YDWM'?'生产、库存或工资账':'黑湖'}}。</small></footer>
 </section>
</template>
